solution.solution.cpp:
#include <cctype>
#include <functional>
#include <map>
#include <string>
#include <vector>

std::string normalizePath(const std::string& path)
{
    std::vector<std::string> parts;
    std::string part;
    auto flush = [&] {
        if (part.empty() || part == ".") { part.clear(); return; }
        if (part == ".." && !parts.empty() && parts.back() != "..") parts.pop_back();
        else parts.push_back(part);
        part.clear();
    };
    for (char c : path)
    {
        if (c == '/' || c == '\\') flush();
        else part += static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    }
    flush();
    std::string out;
    for (std::size_t i{ 0 }; i < parts.size(); ++i) out += (i ? "/" : "") + parts[i];
    return out;
}

class AssetCache
{
public:
    AssetCache(std::function<int(const std::string&)> load, std::function<void(int)> unload)
        : m_load{ std::move(load) }, m_unload{ std::move(unload) } {}

    ~AssetCache()
    {
        for (auto& [path, e] : m_entries) m_unload(e.handle);
    }

    AssetCache(const AssetCache&) = delete;
    AssetCache& operator=(const AssetCache&) = delete;

    int acquire(const std::string& path)
    {
        const std::string key{ normalizePath(path) };
        auto it{ m_entries.find(key) };
        if (it != m_entries.end()) { ++it->second.users; return it->second.handle; }
        const int handle{ m_load(key) };
        if (handle == 0) return 0;
        m_entries[key] = { handle, 1 };
        return handle;
    }

    void release(const std::string& path)
    {
        auto it{ m_entries.find(normalizePath(path)) };
        if (it == m_entries.end()) return;
        if (--it->second.users == 0)
        {
            m_unload(it->second.handle);
            m_entries.erase(it);
        }
    }

    int users(const std::string& path) const
    {
        auto it{ m_entries.find(normalizePath(path)) };
        return it == m_entries.end() ? 0 : it->second.users;
    }

    std::size_t loaded() const { return m_entries.size(); }

private:
    struct Entry { int handle; int users; };
    std::function<int(const std::string&)> m_load;
    std::function<void(int)> m_unload;
    std::map<std::string, Entry> m_entries;
};

unitTests:
struct Fake { int next = 1; std::vector<std::string> loads; std::vector<int> unloads; };
TEST("paths") {
    CHECK_EQ(normalizePath("Assets\\.\\sprites//../Player.PNG"), std::string("assets/player.png"));
    CHECK_EQ(normalizePath("../shared/a.png"), std::string("../shared/a.png")); CHECK_EQ(normalizePath("a/b/../../c"), std::string("c"));
    CHECK_EQ(normalizePath("./"), std::string(""));
}
TEST("loaded once, shared") {
    Fake f;
    {
        AssetCache c{ [&](const std::string& p) { f.loads.push_back(p); return f.next++; }, [&](int h) { f.unloads.push_back(h); } };
        const int a = c.acquire("assets/player.png"), b = c.acquire("Assets\\Player.png");
        CHECK_EQ(a, 1); CHECK_EQ(b, 1); CHECK_EQ(f.loads.size(), std::size_t{ 1 }); CHECK_EQ(c.users("assets/./player.png"), 2);
        c.release("assets/player.png"); CHECK(f.unloads.empty()); c.release("assets/player.png"); CHECK_EQ(f.unloads, (std::vector<int>{ 1 }));
        CHECK_EQ(c.loaded(), std::size_t{ 0 }); CHECK_EQ(c.acquire("assets/player.png"), 2); c.acquire("assets/enemy.png");
        c.release("never/loaded.png");
    }
    CHECK_EQ(f.unloads.size(), std::size_t{ 3 });
}
TEST("failed loads are not cached") {
    int calls = 0;
    AssetCache c{ [&](const std::string&) { ++calls; return 0; }, [](int) {} };
    CHECK_EQ(c.acquire("missing.png"), 0); CHECK_EQ(c.acquire("missing.png"), 0); CHECK_EQ(calls, 2); CHECK_EQ(c.loaded(), std::size_t{ 0 }); CHECK_EQ(c.users("missing.png"), 0);
}

